package network.conet.chat.nativekey

import org.json.JSONObject

/**
 * The `ready` answer to init. When the stored PGP and chat material cannot be read, the answer says so: the state is unknown
 * (`unreadable`), never "no PGP". The account part still succeeds (Y.94); nothing is written or generated by this answer.
 */
internal object InitReadyAnswer {
    const val PGP_STATE = "pgpState"
    const val UNREADABLE = "unreadable"

    fun payload(reqId: Any, pgpStoreUnreadable: Boolean): JSONObject {
        val answer = JSONObject().put("type", "ready").put("reqId", reqId)
        if (pgpStoreUnreadable) answer.put(PGP_STATE, UNREADABLE)
        return answer
    }
}
